import {expect,it} from 'bun:test';
import {join} from 'node:path';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {OwnedDatabase} from '../src/infrastructure/database/owned-database';
import {createSchema} from '../src/infrastructure/database/schema';
import {appendEvent,rebuildProjectionsWithReport} from '../src/infrastructure/database/event-log';
import {Fact} from '../src/domain/entities/fact';

for(const scenario of ['late-write-failure','missing-explicit-log'])it('preserves prior facts on '+scenario,async()=>{
 const storage=createOwnedTestDirectory('memory-replay-integrity-probe-'),db=new OwnedDatabase(':memory:');
 try{
  createSchema(db);db.exec("INSERT INTO facts (uuid,type,project,content,observed_at) VALUES ('retained','learning','synthetic','retainedneedle','2026-01-01T00:00:00Z')");
  const path=join(storage.dir,'events-synthetic.jsonl');
  if(scenario==='late-write-failure'){
   await appendEvent(Fact.create({uuid:'incoming',type:'learning',project:'synthetic',content:'incomingneedle',observedAt:new Date('2026-01-02T00:00:00Z')}),path);
   db.exec("CREATE TRIGGER reject_replay BEFORE INSERT ON facts BEGIN SELECT RAISE(ABORT,'synthetic replay failure'); END");
  }
  let error:string|null=null;try{await rebuildProjectionsWithReport(db,path);}catch(cause){error=cause instanceof Error?cause.message:String(cause);}
  using statement=db.prepare("SELECT uuid FROM facts ORDER BY uuid");const after=statement.all();
  console.log(JSON.stringify({scenario,error,after,expected:[{uuid:'retained'}]}));
  expect(after).toEqual([{uuid:'retained'}]);
 }finally{db.close();storage.cleanup();}
});

