import {strict as assert} from 'node:assert';
import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {discoverInventory,validateInventory,sourceHash} from '../scripts/quality-inventory';
const base='.planning/memory-resilience/',read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const path=base+'evidence/B11.74.5-event.json',record=read(path),catalog=discoverInventory(process.cwd());
assert.equal(catalog.files.length,461);assert.equal(catalog.packages.length,2);assert.deepEqual(catalog,read(base+'executable-catalog.json'));assert.deepEqual(validateInventory(catalog,read(base+'quality-classifications.json')),[]);
for(const input of [...record.sourceInputs,...record.otherInputs,...record.checks[0].sourceInputs,...record.native.sourceInputs])assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')));
assert.equal(record.sourceInputs.length,2);for(const input of record.sourceInputs)for(const rows of [record.diagnosticCoverage.sourceInputs,record.decisionChecks.sourceInputs,record.checks[0].sourceInputs,record.native.sourceInputs])assert.equal(rows.find((r:any)=>r.path===input.path).sourceHash,input.sourceHash);
const coverage=createCoverageMap(record.diagnosticCoverage.measurement.rawCoverage);for(const [index,entry]of record.diagnosticCoverage.measurement.files.entries()){assert.deepEqual(coverage.fileCoverageFor(resolve(entry.path)).toSummary().data,entry.metrics);assert.deepEqual(['lines','functions','statements','branches'].map(k=>entry.metrics[k].pct),index===0?[95.97,100,96.03,91.89]:[100,100,100,100]);}
for(const run of [record.checks[0],record.native.runs[1]]){assert.equal(run.exit,0);assert(run.output.includes('33 pass')&&run.output.includes('0 fail')&&run.output.includes('454 expect()'));}
for(const check of record.checks)assert.equal(check.exit,0);assert.equal(record.checks[2].output.trim(),'');assert(record.checks[3].output.includes('PASS (no violations)'));
assert.equal(record.decisionChecks.runs.length,9);assert.equal(record.decisionChecks.runs[0].exit,0);for(const run of record.decisionChecks.runs.slice(1)){assert.equal(run.exit,1);assert(run.output.includes('(fail)'));}
assert(record.red[0].output.includes('3 fail'));assert(record.red[1].output.includes('1 fail'));
assert.equal(record.replayIntegrityProbe.current.exit,1);assert(record.replayIntegrityProbe.current.output.includes('1 pass')&&record.replayIntegrityProbe.current.output.includes('1 fail'));assert.equal(record.replayIntegrityProbe.source,readFileSync('.git/b11-event-atomicity-probe.test.ts','utf8'));
assert(!existsSync(record.removedRuntimeRoot));
const source=readFileSync(record.sourceInputs[0].path,'utf8');assert.equal([...source.matchAll(/\.prepare[<(]/g)].length,2);assert.equal([...source.matchAll(/using \w+ =/g)].length,2);
const exportPath=base+'evidence/B11.74.5-export.json',exportProof=read(exportPath);
for(const input of [...exportProof.sourceInputs,...exportProof.otherInputs,...exportProof.checks[0].sourceInputs,...exportProof.native.sourceInputs])assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')));
assert.deepEqual(exportProof.native.runs,[record.native.runs[0]]);assert.equal(record.native.runs[0].exit,0);assert(record.native.runs[0].output.includes('35 pass')&&record.native.runs[0].output.includes('747 expect()'));assert(exportProof.olderRuntime.status.startsWith('verified'));assert.equal(exportProof.olderRuntime.followupEvidence,path);assert(exportProof.validationHistory[0].result.includes('disk-blocked'));
const ledger=read(base+'work-items.json'),items=new Map<string,any>(ledger.items.map((i:any)=>[i.id,i])),done=new Set<string>();
function visit(id:string,stack=new Set<string>()){assert(items.has(id)&&!stack.has(id),'Invalid dependency '+id);if(done.has(id))return;for(const dep of items.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);}
assert.equal(items.size,237);assert.equal(items.size,ledger.items.length);for(const id of items.keys())visit(id);
assert.equal(ledger.current_item,'B11.74.5');assert.deepEqual(ledger.items.filter((i:any)=>i.status==='active').map((i:any)=>i.id),['B11.74.5']);
assert.equal(items.get('Q100').status,'pending');assert.deepEqual(items.get('Q100').depends_on,['B11.74.5']);for(const barrier of ['B11.74.7','B10'])assert(items.get(barrier).depends_on.includes('Q100'));assert(items.get('R04').progress.consumerReplayNotice);
assert.equal(items.get('B11.74').status,'pending');assert.equal(items.get('B11.74.6').status,'pending');assert(!readFileSync('src/infrastructure/database/connection.ts','utf8').includes('OwnedDatabase'));
record.validation={command:'bun .git/b11-event-validate.ts',exit:0,recordedAt:new Date().toISOString(),result:'461-file/two-package catalog and237-item acyclic ledger reconcile. Event33tests/454assertions and export35tests/747assertions bind to current inputs and both Windows runtimes. Eight event faults detected. Production branch gap and late replay data loss remain mandatory Q100; B11.74.5 secret-audit work remains active.',source:readFileSync('.git/b11-event-validate.ts','utf8')};
exportProof.validation={...record.validation,result:'Prior export validation retained in history. Current native1.3.14 export group passes35tests/747assertions at the same source/fixture hashes; current-runtime/diagnostic/fault proof remains retained. Full Q004 and baseline acceptance remain open.'};
writeFileSync(path,JSON.stringify(record,null,2)+'\n');writeFileSync(exportPath,JSON.stringify(exportProof,null,2)+'\n');console.log(record.validation.result);
